    public Event reduce(Event e1, Event e2) {
        return new Event(
            e1.getKey(),
            e1.getCount() + e2.getCount()
        );
    }
});
```

### Aggregate Function
More flexible aggregation:
```java
.window(EventTimeSessionWindows.withGap(Time.minutes(10)))
.aggregate(new AggregateFunction<Event, Accumulator, Result>() {
    @Override
    public Accumulator createAccumulator() {
        return new Accumulator();
    }

    @Override
    public Accumulator add(Event value, Accumulator accumulator) {
        accumulator.add(value);
        return accumulator;
    }

    @Override
    public Result getResult(Accumulator accumulator) {
        return accumulator.getResult();
    }

    @Override
    public Accumulator merge(Accumulator a, Accumulator b) {
        return a.merge(b);
    }
});
```

### Process Window Function
Full access to window context:
```java
.window(EventTimeSessionWindows.withGap(Time.minutes(10)))
.process(new ProcessWindowFunction<Event, Result, Key, TimeWindow>() {
    @Override
    public void process(
        Key key,
        Context context,
        Iterable<Event> elements,
        Collector<Result> out
    ) {
        // Access window start/end
        long windowStart = context.window().getStart();
        long windowEnd = context.window().getEnd();

        // Process all elements
        int count = 0;
        for (Event e : elements) {
            count++;
        }

        out.collect(new Result(key, count, windowStart, windowEnd));
    }
});
```

## Custom Session Window Logic with Process Function

For more control, use KeyedProcessFunction with timers:

```java
public class SessionDetector extends KeyedProcessFunction<Long, Event, SessionResult> {
    private static final long SESSION_TIMEOUT = 10 * 60 * 1000; // 10 minutes

    // State to hold events in current session
    private transient ListState<Event> sessionEvents;

    // State to track last event time
    private transient ValueState<Long> lastEventTime;

    @Override
    public void open(Configuration parameters) {
        ListStateDescriptor<Event> eventsDescriptor =
            new ListStateDescriptor<>("sessionEvents", Event.class);
        sessionEvents = getRuntimeContext().getListState(eventsDescriptor);

        ValueStateDescriptor<Long> timeDescriptor =
            new ValueStateDescriptor<>("lastEventTime", Long.class);
        lastEventTime = getRuntimeContext().getState(timeDescriptor);
    }

    @Override
    public void processElement(
        Event event,
        Context ctx,
        Collector<SessionResult> out
    ) throws Exception {
        // Add event to session
        sessionEvents.add(event);

        // Update last event time
        lastEventTime.update(event.getTimestamp());

        // Register timer for session timeout
        long timerTime = event.getTimestamp() + SESSION_TIMEOUT;
        ctx.timerService().registerEventTimeTimer(timerTime);
    }

    @Override
    public void onTimer(
        long timestamp,
        OnTimerContext ctx,
        Collector<SessionResult> out
    ) throws Exception {
        // Check if this timer is still valid
        Long lastTime = lastEventTime.value();
        if (lastTime != null && timestamp == lastTime + SESSION_TIMEOUT) {
            // Session ended - emit result
            List<Event> events = new ArrayList<>();
            for (Event e : sessionEvents.get()) {
                events.add(e);
            }

            out.collect(new SessionResult(ctx.getCurrentKey(), events.size()));

            // Clear session state
            sessionEvents.clear();
            lastEventTime.clear();
        }
    }
}
```

## Complete Example: User Session Analysis

```java
public class UserSessionAnalysis {
    public static void main(String[] args) throws Exception {
        StreamExecutionEnvironment env =
            StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<ClickEvent> clicks = env.addSource(new ClickSource());

        DataStream<ClickEvent> withTimestamps = clicks
            .assignTimestampsAndWatermarks(
                WatermarkStrategy
                    .<ClickEvent>forMonotonousTimestamps()
                    .withTimestampAssigner((event, ts) -> event.getTimestamp())
            );

        DataStream<SessionStats> sessionStats = withTimestamps
            .keyBy(click -> click.getUserId())
            .window(EventTimeSessionWindows.withGap(Time.minutes(30)))
            .aggregate(new SessionAggregator());

        sessionStats.print();

        env.execute("User Session Analysis");
    }

    public static class SessionAggregator
        implements AggregateFunction<ClickEvent, SessionAccumulator, SessionStats> {

        @Override
        public SessionAccumulator createAccumulator() {
            return new SessionAccumulator();
        }

        @Override
        public SessionAccumulator add(ClickEvent value, SessionAccumulator acc) {
            acc.clickCount++;
            if (acc.firstClick == 0) {
                acc.firstClick = value.getTimestamp();
            }
            acc.lastClick = value.getTimestamp();
            return acc;
        }

        @Override
        public SessionStats getResult(SessionAccumulator acc) {
            return new SessionStats(
                acc.clickCount,
                acc.lastClick - acc.firstClick
            );
        }

        @Override
        public SessionAccumulator merge(SessionAccumulator a, SessionAccumulator b) {
            a.clickCount += b.clickCount;
            a.firstClick = Math.min(a.firstClick, b.firstClick);
            a.lastClick = Math.max(a.lastClick, b.lastClick);
            return a;
        }
    }

    public static class SessionAccumulator {
        long clickCount = 0;
        long firstClick = 0;
        long lastClick = 0;
    }
}
```

## Handling Late Events

### Allowed Lateness
Allow late events to still update windows:
```java
stream
    .keyBy(event -> event.getKey())
    .window(EventTimeSessionWindows.withGap(Time.minutes(10)))
    .allowedLateness(Time.minutes(2))
    .reduce((e1, e2) -> combine(e1, e2));
```

### Side Outputs for Late Data
Capture late events separately:
```java
final OutputTag<Event> lateOutputTag = new OutputTag<Event>("late-data"){};

SingleOutputStreamOperator<Result> result = stream
    .keyBy(event -> event.getKey())
    .window(EventTimeSessionWindows.withGap(Time.minutes(10)))
    .sideOutputLateData(lateOutputTag)
    .reduce((e1, e2) -> combine(e1, e2));

DataStream<Event> lateStream = result.getSideOutput(lateOutputTag);
```

## Resources
- [Flink Windows Documentation](https://nightlies.apache.org/flink/flink-docs-stable/docs/dev/datastream/operators/windows/)
- [Event Time and Watermarks](https://nightlies.apache.org/flink/flink-docs-stable/docs/concepts/time/)

