# Reading Gzipped CSV Files in Apache Flink

## Overview
Apache Flink can read CSV files from various sources. When dealing with compressed (gzipped) CSV files, you need to handle decompression before parsing.

## Reading Gzipped CSV with Custom Source Function

### Basic Source Function Template
```java
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import java.io.*;
import java.util.zip.GZIPInputStream;

public class GzipCsvSourceFunction<T> implements SourceFunction<T> {
    private final String filePath;
    private final CsvParser<T> parser;
    private volatile boolean isRunning = true;

    public GzipCsvSourceFunction(String filePath, CsvParser<T> parser) {
        this.filePath = filePath;
        this.parser = parser;
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        InputStream fileInputStream = new FileInputStream(filePath);
        InputStream inputStream;

        // Check if file is gzipped
        if (filePath.endsWith(".gz")) {
            inputStream = new GZIPInputStream(fileInputStream);
        } else {
            inputStream = fileInputStream;
        }

        BufferedReader reader = new BufferedReader(
            new InputStreamReader(inputStream)
        );

        String line;
        while (isRunning && (line = reader.readLine()) != null) {
            try {
                T record = parser.parse(line);
                synchronized (ctx.getCheckpointLock()) {
                    ctx.collect(record);
                }
            } catch (Exception e) {
                // Handle parse errors
                System.err.println("Error parsing line: " + line);
                e.printStackTrace();
            }
        }

        reader.close();
        inputStream.close();
        fileInputStream.close();
    }

    @Override
    public void cancel() {
        isRunning = false;
    }

    public interface CsvParser<T> extends Serializable {
        T parse(String line) throws Exception;
    }
}
```

### Usage Example
```java
public class ReadGzipCsvExample {
    public static void main(String[] args) throws Exception {
        StreamExecutionEnvironment env =
            StreamExecutionEnvironment.getExecutionEnvironment();

        // Create source with parser
        DataStream<MyRecord> stream = env.addSource(
            new GzipCsvSourceFunction<>(
                "/path/to/file.csv.gz",
                line -> MyRecord.fromCsv(line)
            )
        );

        stream.print();

        env.execute("Read Gzip CSV");
    }
}
```

## Custom RichSourceFunction for Better Control

RichSourceFunction provides access to runtime context and lifecycle methods:

```java
import org.apache.flink.streaming.api.functions.source.RichSourceFunction;
import org.apache.flink.configuration.Configuration;

public class GzipCsvRichSource<T> extends RichSourceFunction<T> {
    private final String filePath;
    private final CsvParser<T> parser;
    private volatile boolean isRunning = true;

    public GzipCsvRichSource(String filePath, CsvParser<T> parser) {
        this.filePath = filePath;
        this.parser = parser;
    }

    @Override
    public void open(Configuration parameters) throws Exception {
        super.open(parameters);
        // Initialize resources
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        InputStream fileInputStream = new FileInputStream(filePath);
        InputStream inputStream = filePath.endsWith(".gz")
            ? new GZIPInputStream(fileInputStream)
            : fileInputStream;

        BufferedReader reader = new BufferedReader(
            new InputStreamReader(inputStream)
        );

        String line;
        while (isRunning && (line = reader.readLine()) != null) {
            T record = parser.parse(line);
            synchronized (ctx.getCheckpointLock()) {
                ctx.collect(record);
            }
        }

        reader.close();
    }

    @Override
    public void cancel() {
        isRunning = false;
    }

    @Override
    public void close() throws Exception {
        super.close();
        // Cleanup resources
    }

    @FunctionalInterface
    public interface CsvParser<T> extends Serializable {
        T parse(String line) throws Exception;
    }
}
```

## Parsing CSV Lines

### Simple CSV Parser
```java
public class SimpleRecord {
    private long id;
    private String name;
    private int value;

    public static SimpleRecord fromCsv(String line) {
