            seenIds.put(eventId, newExpiration);

            // Register cleanup timer
            ctx.timerService().registerEventTimeTimer(newExpiration);
        }
        // Else: duplicate within window - drop
    }

    @Override
    public void onTimer(
        long timestamp,
        OnTimerContext ctx,
        Collector<Event> out
    ) throws Exception {
        // Clean up expired entries
        Iterator<Map.Entry<String, Long>> iterator =
            seenIds.entries().iterator();

        while (iterator.hasNext()) {
            Map.Entry<String, Long> entry = iterator.next();
            if (entry.getValue() <= timestamp) {
                iterator.remove();
            }
        }
    }
}
```

## Side Outputs

Emit to multiple output streams:

```java
