import org.apache.flink.streaming.api.functions.source.RichSourceFunction;

import java.io.*;
import java.util.zip.GZIPInputStream;

public class TaskEventSource extends RichSourceFunction<TaskEvent> {
    private final String filePath;
    private volatile boolean isRunning = true;

    public TaskEventSource(String filePath) {
        this.filePath = filePath;
    }

    @Override
    public void run(SourceContext<TaskEvent> ctx) throws Exception {
        InputStream fileStream = new FileInputStream(filePath);
        InputStream inputStream = filePath.endsWith(".gz")
                ? new GZIPInputStream(fileStream)
                : fileStream;

        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));

        String line;
        while (isRunning && (line = reader.readLine()) != null) {
            try {
                TaskEvent event = TaskEvent.fromCsv(line);
                synchronized (ctx.getCheckpointLock()) {
                    ctx.collect(event);
                }
            } catch (Exception e) {
                System.err.println("Error parsing task event line: " + line);
                e.printStackTrace();
            }
        }

        reader.close();
        inputStream.close();
        fileStream.close();
    }

    @Override
    public void cancel() {
        isRunning = false;
    }
}

